solution.javascript:
class Table {
  constructor(seats) {
    this.seats = seats
    this.guests = []
  }

  seat(name) {
    if (this.guests.length >= this.seats) {
      return false
    }
    this.guests.push(name)
    return true
  }

  freeSeats() {
    return this.seats - this.guests.length
  }
}

