solution.javascript:
function everyOtherValue(head) {
  const values = []
  let current = head
  let position = 0
  while (current !== null) {
    if (position % 2 === 0) {
      values.push(current.value)
    }
    position = position + 1
    current = current.next
  }
  return values
}
